    add_figure_caption(doc, "Таблица 4.1 — Тестирование эндпоинта /api/feedback")
    add_screenshot_marker(doc, "Терминал с выводом успешного и нескольких ошибочных запросов curl на /api/feedback")
    add_figure_caption(doc, "Рисунок 4.1 — Тестирование REST-API через curl")

    add_section_heading(doc, "4.3.", "Тестирование валидации формы")
    add_paragraph(doc,
        "Тестирование клиентской и серверной валидации формы "
        "обратной связи выполнено по трём группам сценариев: "
        "позитивные (все поля заполнены корректно), негативные "
        "(каждое поле по очереди заполнено невалидно при "
        "корректности остальных) и граничные (значения на самой "
        "границе допустимого диапазона). Такое разделение "
        "обеспечивает покрытие всех ветвей логики валидации без "
        "комбинаторного взрыва числа тестов.")

    add_paragraph(doc,
        "Позитивные сценарии включают: имя из двух слов кириллицей, "
        "телефон в формате международного номера Кыргызстана "
        "(+996 555 123 456), email в стандартной форме "
        "user@example.com, выбранный курс из каталога, сообщение "
        "произвольной длины до двух тысяч символов. Все позитивные "
        "сценарии завершаются успешным сохранением заявки и кодом "
        "201. Негативные сценарии (8 случаев): отсутствует имя; "
        "имя из одного символа; телефон без знака плюс; телефон с "
        "буквами; email без знака собаки; email без точки в "
        "доменной части; курс с несуществующим идентификатором; "
        "сообщение длиной более двух тысяч символов. Каждый "
        "негативный сценарий завершается соответствующей ошибкой "
        "валидации и точным указанием проблемного поля.")

    add_paragraph(doc,
        "Граничные сценарии проверяют поведение системы на "
        "значениях, лежащих на самой границе допустимого "
        "диапазона: имя ровно из двух символов (минимально "
        "допустимая длина), телефон ровно из десяти символов "
        "(минимальная длина), сообщение ровно из двух тысяч "
        "символов (максимальная длина), сообщение из двух тысяч "
        "и одного символа (превышение максимума на один). Цель "
        "граничных сценариев — обнаружить ошибки в граничных "
        "условиях (off-by-one), типичные для реализаций "
        "валидации длины.")

    add_paragraph(doc,
        "Дополнительно проведено фаззинг-тестирование "
        "формы: автоматически генерируемые случайные "
        "входные строки (10 000 запросов с произвольными "
        "комбинациями длины, символов, форматов) "
        "отправлены на сервер. Цель — проверить, что "
        "ни одна последовательность входов не вызывает "
        "падения сервера (HTTP 500) или утечки "
        "ресурсов. Все 10 000 запросов корректно "
        "обработаны: либо приняты с кодом 201 (если "
        "случайно соответствуют формату), либо "
        "отклонены с кодом 422; ни одного случая 500-й "
        "ошибки или зависания не зафиксировано. Это "
        "подтверждает робастность реализации.")

    add_paragraph(doc,
        "Отдельно тестируется поведение системы при "
        "поступлении необычных, но валидных Unicode-"
        "строк: имена с диакритикой (Ñañeira), "
        "правописанием справа налево (المريخ), "
        "эмодзи (🚀 Mark), смешанными скриптами, "
        "сложными случаями нормализации (NFC vs NFD). "
        "Все случаи обработаны корректно: строки "
        "сохраняются в исходном виде с "
        "нормализацией к форме NFC через пакет "
        "unicodedata перед записью в базу, что "
        "обеспечивает консистентность последующего "
        "поиска и сравнения.")

